function CompletionProgress({ current, total, label = "Заполнено" }: { current: number; total: number; label?: string }) {
  const percent = total ? Math.round((current / total) * 100) : 0;
  return <div className="completion"><div><span>{label}</span><b>{current} из {total} · {percent}%</b></div><div className="progress-bar"><i style={{ width: `${percent}%` }} /></div></div>;
}

function Toast({ message, tone, onClose }: { message: string; tone: string; onClose: () => void }) {
  useEffect(() => { const timer = window.setTimeout(onClose, 2600); return () => window.clearTimeout(timer); }, [onClose]);
  return <div className={`toast ${tone}`} role="status"><CheckCircle2 size={19}/><span>{message}</span><button onClick={onClose} aria-label="Закрыть сообщение"><X size={16}/></button></div>;
}

function Dialog({ title, text, confirmLabel = "Продолжить", danger = false, onConfirm, onClose }: { title: string; text: string; confirmLabel?: string; danger?: boolean; onConfirm: () => void; onClose: () => void }) {
  return <div className="dialog-layer" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><div className="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div className={`dialog-icon ${danger ? "danger" : ""}`}>{danger ? <Trash2/> : <AlertCircle/>}</div><h2 id="dialog-title">{title}</h2><p>{text}</p><div className="dialog-actions"><button className="btn secondary" onClick={onClose}>Отмена</button><button className={`btn ${danger ? "danger-btn" : ""}`} onClick={onConfirm}>{confirmLabel}</button></div></div></div>;
}

function useUnsavedGuard(dirty: boolean) {
  const router = useRouter();
  const [pendingHref, setPendingHref] = useState<string | null>(null);
  useEffect(() => {
    const beforeUnload = (event: BeforeUnloadEvent) => { if (dirty) event.preventDefault(); };
    const linkGuard = (event: MouseEvent) => {
      const link = (event.target as HTMLElement).closest("a");
      if (!dirty || !link?.href || link.target === "_blank") return;
      const target = new URL(link.href);
      if (target.origin !== window.location.origin || target.pathname === window.location.pathname) return;
      event.preventDefault(); setPendingHref(target.pathname);
    };
    window.addEventListener("beforeunload", beforeUnload); document.addEventListener("click", linkGuard, true);
    return () => { window.removeEventListener("beforeunload", beforeUnload); document.removeEventListener("click", linkGuard, true); };
  }, [dirty]);
  const dialog = pendingHref ? <Dialog title="Есть несохранённые изменения" text="Если уйти со страницы сейчас, внесённые данные будут потеряны." confirmLabel="Уйти без сохранения" onClose={() => setPendingHref(null)} onConfirm={() => { const href = pendingHref; setPendingHref(null); router.push(href); }} /> : null;
  return { dialog, requestCancel: () => dirty ? setPendingHref("/teacher") : router.push("/teacher") };
}

