const attendanceOptions: AttendanceStatus[]=["Присутствовал","Отсутствовал","Опоздал","Уважительная причина","Занятие отменено"];
function AttendanceStatusSelector({ value, onChange }: { value: AttendanceStatus; onChange: (value: AttendanceStatus)=>void }) {
  return <div className="status-selector">{attendanceOptions.map((status)=><button type="button" title={status} aria-label={status} className={`${value===status?"active":""} status-${attendanceOptions.indexOf(status)}`} onClick={()=>onChange(status)} key={status}>{status==="Присутствовал"?"Был":status==="Отсутствовал"?"Нет":status==="Опоздал"?"Опоздал":status==="Уважительная причина"?"Уваж.":"Отмена"}</button>)}</div>;
}

function AttendanceRegister({ ui, groupId = "kids-starter" }: { ui: TeacherUI; groupId?: string }) {
  const { SectionCard, Button }=ui; const students=teacherStudents.filter((student)=>student.groupId===groupId);
  const [statuses,setStatuses]=useState<Record<string,AttendanceStatus>>(()=>Object.fromEntries(students.map((s)=>[s.id,""]))); const [dirty,setDirty]=useState(false); const [comment,setComment]=useState(""); const [error,setError]=useState(""); const [saving,setSaving]=useState(false); const guard=useUnsavedGuard(dirty);
  const setAll=(status:AttendanceStatus)=>{setStatuses(Object.fromEntries(students.map((s)=>[s.id,status])));setDirty(true);setError("")};
  const save=()=>{if(Object.values(statuses).some((status)=>!status)){setError("Выберите статус для каждого ученика.");return}setSaving(true);window.setTimeout(()=>{setSaving(false);setDirty(false);setError("");},650)};
  return <><SectionCard title="Параметры занятия"><div className="compact-form"><label><span>Группа *</span><select defaultValue={groupId}><option value={groupId}>{groupName(groupId)}</option></select></label><label><span>Дата *</span><input type="date" defaultValue="2025-05-30"/></label><label><span>Урок или тема *</span><select><option>Unit 3 · My Family</option><option>Unit 3 · He is my brother</option></select></label><label className="wide"><span>Комментарий к занятию</span><input value={comment} onChange={(event)=>{setComment(event.target.value);setDirty(true)}} placeholder="Необязательно"/></label></div></SectionCard><section className="attendance-toolbar"><div><b>Журнал посещаемости</b><span>{groupName(groupId)} · {students.length} учеников</span></div><div><button onClick={()=>setAll("Присутствовал")}><Check size={16}/>Все присутствовали</button><button onClick={()=>setAll("")}><RotateCcw size={16}/>Сбросить</button><button onClick={()=>{setAll("Присутствовал");const first=students[3];if(first)setStatuses((prev)=>({...prev,[first.id]:"Отсутствовал"}))}}><Copy size={16}/>Из прошлого урока</button></div></section><SectionCard className="attendance-card"><div className="attendance-register"><div className="attendance-register-head"><span>Ученик</span><span>Статус</span></div>{students.map((student)=><div className="attendance-student" key={student.id}><div><span className="avatar">{student.initials}</span><div><b>{student.name}</b><small>Посещаемость за месяц: {student.attendance}%</small></div></div><AttendanceStatusSelector value={statuses[student.id]} onChange={(status)=>{setStatuses((prev)=>({...prev,[student.id]:status}));setDirty(true);setError("")}}/></div>)}</div>{error&&<p className="form-error"><AlertCircle size={15}/>{error}</p>}</SectionCard><div className="sticky-save"><span>{dirty?"Есть несохранённые изменения":"Все изменения сохранены"}</span><Button secondary onClick={guard.requestCancel}>Отмена</Button><Button disabled={saving} onClick={save}>{saving?<Loader2 className="spin" size={17}/>:<Save size={17}/>}Сохранить</Button></div>{guard.dialog}</>;
}

interface WordField { id: number; word: string; translation: string; note: string }
function DynamicWordFields({ rows, onChange }: { rows: WordField[]; onChange: (rows: WordField[])=>void }) {
  const update=(id:number,key:keyof WordField,value:string)=>onChange(rows.map((row)=>row.id===id?{...row,[key]:value}:row));
  return <div className="dynamic-words"><div className="dynamic-head"><b>Изученные слова</b><button type="button" onClick={()=>onChange([...rows,{id:Date.now(),word:"",translation:"",note:""}])}><Plus size={15}/>Добавить строку</button></div>{rows.map((row,index)=><div className="word-row" key={row.id}><span>{index+1}</span><input value={row.word} onChange={(e)=>update(row.id,"word",e.target.value)} placeholder="English word"/><input value={row.translation} onChange={(e)=>update(row.id,"translation",e.target.value)} placeholder="Перевод"/><input value={row.note} onChange={(e)=>update(row.id,"note",e.target.value)} placeholder="Пример или примечание"/><button type="button" disabled={rows.length===1} onClick={()=>onChange(rows.filter((item)=>item.id!==row.id))} aria-label="Удалить слово"><Trash2 size={16}/></button></div>)}</div>;
}

function LessonForm({ ui, notify, onDone }: { ui: TeacherUI; notify: Notify; onDone?: ()=>void }) {
  const { SectionCard, Button }=ui; const [book,setBook]=useState("Family and Friends 1"); const [unit,setUnit]=useState(""); const [topic,setTopic]=useState(""); const [dirty,setDirty]=useState(false); const [saving,setSaving]=useState(false); const [errors,setErrors]=useState<string[]>([]); const [words,setWords]=useState<WordField[]>([{id:1,word:"",translation:"",note:""}]); const guard=useUnsavedGuard(dirty);
  const units=book==="Family and Friends 1"?["Unit 2","Unit 3"]:book==="Academy Stars 1"?["Unit 4","Unit 5"]:["Unit 3","Unit 4"];
  const topics:Record<string,string[]>={"Unit 2":["My Toys","At School"],"Unit 3":["My Family","He is my brother"],"Unit 4":["Life online","Grammar Review"],"Unit 5":["At the park","Outdoor activities"]};
  const submit=(event:React.FormEvent)=>{event.preventDefault();const next=[];if(!unit)next.push("Выберите раздел.");if(!topic)next.push("Выберите тему, относящуюся к разделу.");if(words.some((row)=>row.word&&!row.translation))next.push("Добавьте перевод для каждого введённого слова.");setErrors(next);if(next.length)return;setSaving(true);window.setTimeout(()=>{setSaving(false);setDirty(false);notify("Урок сохранён и добавлен в журнал");onDone?.()},700)};
  return <><form onSubmit={submit} onChange={()=>setDirty(true)}><SectionCard title="Основная информация"><div className="form-grid teacher-form"><label><span>Дата *</span><input type="date" defaultValue="2025-05-30" required/></label><label><span>Группа *</span><select required><option>Kids Starter</option><option>Kids A1</option><option>Teens A2</option></select></label><label><span>Учебник *</span><select value={book} onChange={(e)=>{setBook(e.target.value);setUnit("");setTopic("");setDirty(true)}}><option>Family and Friends 1</option><option>Academy Stars 1</option><option>Solutions A2</option></select></label><label><span>Раздел *</span><select value={unit} onChange={(e)=>{setUnit(e.target.value);setTopic("");setDirty(true)}}><option value="">Выберите раздел</option>{units.map((item)=><option key={item}>{item}</option>)}</select></label><label><span>Тема *</span><select value={topic} onChange={(e)=>{setTopic(e.target.value);setDirty(true)}} disabled={!unit}><option value="">{unit?"Выберите тему":"Сначала выберите раздел"}</option>{(topics[unit]??[]).map((item)=><option key={item}>{item}</option>)}</select></label><label><span>Тип занятия *</span><select><option>Обычный урок</option><option>Повторение</option><option>Тест</option><option>Разговорная практика</option><option>Итоговое занятие</option></select></label><label className="full"><span>Краткое описание *</span><input placeholder="Например: знакомство с лексикой по теме семьи" required/></label><label className="full"><span>Что изучали *</span><textarea placeholder="Содержание занятия" required/></label><label className="full"><span>Грамматика</span><textarea placeholder="Грамматические конструкции и примеры"/></label></div></SectionCard><section className="section-card form-section"><DynamicWordFields rows={words} onChange={(next)=>{setWords(next);setDirty(true)}}/></section><SectionCard title="Домашнее задание"><div className="form-grid teacher-form"><label><span>Материал</span><select><option>Workbook</option><option>Учебник</option><option>Дополнительный лист</option></select></label><label><span>Страница</span><input type="number" min="1" placeholder="24"/></label><label><span>Упражнения</span><input placeholder="2–3"/></label><label><span>Срок</span><input type="date"/></label><label className="full"><span>Описание</span><textarea placeholder="Что необходимо выполнить"/></label><div className="upload-placeholder"><FileText/><span>Прикреплённый материал</span><button type="button">Выбрать demo-файл</button></div></div></SectionCard><SectionCard title="Комментарии"><div className="form-grid teacher-form"><label className="full"><span>Комментарий для родителей</span><textarea placeholder="Этот текст увидят родители"/></label><label className="full"><span>Внутренний комментарий</span><textarea placeholder="Виден только учителю"/></label></div></SectionCard>{errors.length>0&&<div className="validation-summary"><AlertCircle/><div><b>Проверьте форму</b>{errors.map((error)=><p key={error}>{error}</p>)}</div></div>}<div className="form-actions teacher-actions"><Button secondary onClick={guard.requestCancel}>Отмена</Button><Button disabled={saving} type="submit">{saving?<Loader2 className="spin" size={17}/>:<Save size={17}/>}Сохранить урок</Button></div></form>{guard.dialog}</>;
}

function LessonDetail({ lesson, onClose }: { lesson: typeof teacherLessons[number]; onClose: ()=>void }) {
  return <div className="dialog-layer"><div className="side-sheet" role="dialog" aria-modal="true"><button className="sheet-close" onClick={onClose} aria-label="Закрыть"><X/></button><span className="badge green">{lesson.type}</span><h2>{lesson.topic}</h2><p className="muted">{lesson.date} · {groupName(lesson.groupId)} · {lesson.unit}</p><div className="detail-section"><h3>Что изучали</h3><p>{lesson.learned}</p></div><div className="detail-section"><h3>Новые слова</h3><div className="word-chips"><span>family · семья</span><span>brother · брат</span><span>kind · добрый</span></div></div><div className="detail-section"><h3>Домашнее задание</h3><p>{lesson.homework}</p></div><div className="detail-section"><h3>Посещаемость</h3><p>{lesson.attendance} · 7 из 8 учеников присутствовали</p></div><div className="detail-section"><h3>Связанные результаты</h3><p>Для этого урока тест не проводился.</p></div></div></div>;
}

function LessonsJournal({ ui, groupId, notify, initialCreate = false }: { ui: TeacherUI; groupId?: string; notify?: Notify; initialCreate?: boolean }) {
  const { SectionCard, Button }=ui; const [items,setItems]=useState(teacherLessons.filter((lesson)=>!groupId||lesson.groupId===groupId)); const [creating,setCreating]=useState(initialCreate); const [detail,setDetail]=useState<typeof teacherLessons[number]|null>(null); const [deleting,setDeleting]=useState<string|null>(null);
  if(creating)return <><button className="back-link" onClick={()=>setCreating(false)}><ChevronLeft size={16}/>Вернуться в журнал</button><LessonForm ui={ui} notify={notify??(()=>{})} onDone={()=>setCreating(false)}/></>;
  return <><div className="page-toolbar"><TeacherFilters fields={[groupId?groupName(groupId):"Все группы","Все учебники","Все разделы","Май 2025","Все типы"]} search="" onSearch={()=>{}}/><Button onClick={()=>setCreating(true)}><Plus size={17}/>Добавить урок</Button></div><SectionCard><div className="journal-list">{items.map((lesson)=><article key={lesson.id}><div className="journal-date"><b>{lesson.date.split(" ")[0]}</b><span>{lesson.date.split(" ").slice(1).join(" ")}</span></div><div className="journal-main"><div><span className="badge green">{lesson.type}</span><h3>{lesson.topic}</h3><p>{groupName(lesson.groupId)} · {lesson.unit}</p></div><dl><div><dt>Что изучали</dt><dd>{lesson.learned}</dd></div><div><dt>Новых слов</dt><dd>{lesson.words}</dd></div><div><dt>Домашнее задание</dt><dd>{lesson.homework}</dd></div><div><dt>Учитель</dt><dd>{teacherProfile.name}</dd></div></dl></div><div className="row-actions"><button onClick={()=>setDetail(lesson)} title="Открыть"><Eye size={17}/></button><button onClick={()=>notify?.("Урок открыт для редактирования")} title="Редактировать"><Edit3 size={17}/></button><button onClick={()=>{setItems((prev)=>[{...lesson,id:`copy-${Date.now()}`,date:"Новый черновик"},...prev]);notify?.("Урок продублирован как черновик")}} title="Дублировать"><Copy size={17}/></button><button onClick={()=>setDeleting(lesson.id)} title="Удалить"><Trash2 size={17}/></button></div></article>)}</div></SectionCard>{detail&&<LessonDetail lesson={detail} onClose={()=>setDetail(null)}/>} {deleting&&<Dialog danger title="Удалить урок?" text="Урок и его demo-связи будут удалены из текущего списка." confirmLabel="Удалить" onClose={()=>setDeleting(null)} onConfirm={()=>{setItems((prev)=>prev.filter((item)=>item.id!==deleting));setDeleting(null);notify?.("Урок удалён")}}/>}</>;
}

function HomeworkStudentStatusList({ groupId, onClose, notify }: { groupId: string; onClose: ()=>void; notify: Notify }) {
  const students=teacherStudents.filter((student)=>student.groupId===groupId); const [statuses,setStatuses]=useState<Record<string,string>>(()=>Object.fromEntries(students.map((s)=>[s.id,s.homework])));
  return <div className="dialog-layer"><div className="side-sheet homework-sheet"><button className="sheet-close" onClick={onClose}><X/></button><h2>Статусы учеников</h2><p className="muted">{groupName(groupId)} · домашнее задание</p><div className="homework-students">{students.map((student)=><div key={student.id}><span className="avatar">{student.initials}</span><b>{student.name}</b><select value={statuses[student.id]} onChange={(e)=>setStatuses((prev)=>({...prev,[student.id]:e.target.value}))}><option>Задано</option><option>Выполнено</option><option>Выполнено частично</option><option>Не выполнено</option><option>Проверено</option></select><input placeholder="Индивидуальный комментарий"/></div>)}</div><button className="btn" onClick={()=>{notify("Статусы домашнего задания сохранены");onClose()}}>Сохранить статусы</button></div></div>;
}

function HomeworkForm({ ui, onClose, notify }: { ui: TeacherUI; onClose: ()=>void; notify: Notify }) {
  const { SectionCard, Button }=ui; const [saving,setSaving]=useState(false);
  return <form onSubmit={(e)=>{e.preventDefault();setSaving(true);window.setTimeout(()=>{setSaving(false);notify("Домашнее задание создано");onClose()},600)}}><SectionCard title="Новое домашнее задание"><div className="form-grid teacher-form"><label><span>Группа *</span><select required><option>Kids Starter</option><option>Kids A1</option><option>Teens A2</option></select></label><label><span>Тема *</span><select required><option>My Family</option><option>At the park</option><option>Life online</option></select></label><label><span>Дата выдачи *</span><input type="date" required/></label><label><span>Срок *</span><input type="date" required/></label><label><span>Книга *</span><input placeholder="Workbook" required/></label><label><span>Страница и упражнения *</span><input placeholder="24, упражнения 2–3" required/></label><label className="full"><span>Описание *</span><textarea placeholder="Подробное задание для родителей" required/></label></div><div className="form-actions"><Button secondary onClick={onClose}>Отмена</Button><Button disabled={saving} type="submit">{saving?<Loader2 className="spin"/>:<Save size={17}/>}Создать задание</Button></div></SectionCard></form>;
}

function HomeworkPage({ ui, groupId, notify = ()=>{}, initialCreate = false }: { ui: TeacherUI; groupId?: string; notify?: Notify; initialCreate?: boolean }) {
  const { Button }=ui; const [items,setItems]=useState(teacherHomework.filter((item)=>!groupId||item.groupId===groupId)); const [creating,setCreating]=useState(initialCreate); const [statuses,setStatuses]=useState<string|null>(null); const [deleting,setDeleting]=useState<string|null>(null);
  if(creating)return <HomeworkForm ui={ui} onClose={()=>setCreating(false)} notify={notify}/>;
  return <><div className="page-toolbar"><TeacherFilters fields={[groupId?groupName(groupId):"Все группы","Все ученики","Все статусы","Все учебники","Май 2025"]}/><Button onClick={()=>setCreating(true)}><Plus size={17}/>Создать задание</Button></div><div className="homework-grid">{items.map((item)=><article className="homework-card" key={item.id}><div className="card-top"><div><span className="badge green">{groupName(item.groupId)}</span><h3>{item.topic}</h3></div><div className="row-actions"><button onClick={()=>notify("Задание открыто для редактирования")}><Edit3 size={16}/></button><button onClick={()=>setDeleting(item.id)}><Trash2 size={16}/></button></div></div><p className="muted">Выдано {item.issued} · срок {item.due}</p><div className="homework-detail"><b>{item.book} · стр. {item.page} · упр. {item.exercises}</b><span>{item.description}</span></div><div className="homework-stats"><span className="green"><b>{item.done}</b> выполнено</span><span className="orange"><b>{item.partial}</b> частично</span><span className="red"><b>{item.missing}</b> не выполнено</span><span><b>{item.unchecked}</b> не проверено</span></div><button className="card-link" onClick={()=>setStatuses(item.groupId)}>Открыть учеников <ChevronRight size={15}/></button></article>)}</div>{statuses&&<HomeworkStudentStatusList groupId={statuses} onClose={()=>setStatuses(null)} notify={notify}/>} {deleting&&<Dialog danger title="Удалить задание?" text="Задание исчезнет из demo-списка для всей группы." confirmLabel="Удалить" onClose={()=>setDeleting(null)} onConfirm={()=>{setItems((prev)=>prev.filter((item)=>item.id!==deleting));setDeleting(null);notify("Домашнее задание удалено")}}/>}</>;
}

function WordsPage({ ui, notify }: { ui: TeacherUI; notify: Notify }) {
  const { SectionCard, Button }=ui; const [tab,setTab]=useState("Слова темы"); const [rows,setRows]=useState<WordField[]>([{id:1,word:"family",translation:"семья",note:"My family is big."},{id:2,word:"brother",translation:"брат",note:""}]); const [importText,setImportText]=useState(""); const [student,setStudent]=useState(teacherStudents[0].id); const [statuses,setStatuses]=useState<Record<string,string>>({family:"Освоено",brother:"Изучает",mother:"Уверенно использует",kind:"Нужно повторить"});
  return <><div className="tabs"><button className={tab==="Слова темы"?"active":""} onClick={()=>setTab("Слова темы")}>Слова темы</button><button className={tab==="Прогресс ребёнка"?"active":""} onClick={()=>setTab("Прогресс ребёнка")}>Прогресс ребёнка</button></div>{tab==="Слова темы"?<><SectionCard title="Добавить слова" action={<span className="badge green">Unit 3 · My Family</span>}><div className="compact-form"><label><span>Группа</span><select><option>Kids Starter</option></select></label><label><span>Раздел</span><select><option>Unit 3</option></select></label><label><span>Тема</span><select><option>My Family</option></select></label><label><span>Дата изучения</span><input type="date" defaultValue="2025-05-30"/></label></div><DynamicWordFields rows={rows} onChange={setRows}/><div className="form-actions"><Button onClick={()=>notify("Слова добавлены к теме")}>Сохранить слова</Button></div></SectionCard><SectionCard title="Импорт списком" action={<span className="muted">Формат: word — перевод</span>}><textarea className="import-area" value={importText} onChange={(e)=>setImportText(e.target.value)} placeholder={'family — семья\nbrother — брат\nkind — добрый'}/><Button disabled={!importText.trim()} onClick={()=>{const imported=importText.split("\n").filter(Boolean).map((line,i)=>{const [word,translation]=line.split(/[—-]/).map(x=>x.trim());return{id:Date.now()+i,word,translation:translation??"",note:""}});setRows((prev)=>[...prev,...imported]);setImportText("");notify("Список импортирован")}}>Импортировать</Button></SectionCard></>:<SectionCard title="Индивидуальный словарный прогресс"><div className="compact-form"><label><span>Ученик</span><select value={student} onChange={(e)=>setStudent(e.target.value)}>{teacherStudents.slice(0,8).map((s)=><option value={s.id} key={s.id}>{s.name}</option>)}</select></label><label><span>Тема</span><select><option>My Family</option></select></label></div><div className="vocab-progress">{[["family","семья"],["brother","брат"],["mother","мама"],["kind","добрый"]].map(([word,translation])=><div key={word}><div><b>{word}</b><span>{translation}</span></div><select value={statuses[word]} onChange={(e)=>setStatuses((prev)=>({...prev,[word]:e.target.value}))}><option>Новое</option><option>Изучает</option><option>Нужно повторить</option><option>Освоено</option><option>Уверенно использует</option></select></div>)}</div><div className="form-actions"><Button onClick={()=>notify("Словарный прогресс сохранён")}>Сохранить статусы</Button></div></SectionCard>}</>;
}

function TestResultForm({ ui, notify }: { ui: TeacherUI; notify: Notify }) {
  const { SectionCard, Button }=ui; const [max,setMax]=useState(50); const [score,setScore]=useState(0); const [categories,setCategories]=useState<string[]>(["Speaking","Listening"]); const invalid=score>max||score<0;
  return <SectionCard title="Добавить результат теста"><form onSubmit={(e)=>{e.preventDefault();if(!invalid)notify("Результат теста сохранён")}}><div className="form-grid teacher-form"><label><span>Группа *</span><select><option>Kids Starter</option></select></label><label><span>Ученик *</span><select><option>Амина Серикова</option></select></label><label><span>Название теста *</span><input defaultValue="Unit 3 Test" required/></label><label><span>Раздел *</span><select><option>Unit 3</option></select></label><label><span>Дата *</span><input type="date" required/></label><label><span>Максимальный балл *</span><input type="number" min="1" value={max} onChange={(e)=>setMax(Number(e.target.value))}/></label><label><span>Набранный балл *</span><input className={invalid?"invalid":""} type="number" min="0" value={score} onChange={(e)=>setScore(Number(e.target.value))}/><small>{invalid?"Балл не может превышать максимум":""}</small></label><label><span>Процент</span><input value={`${max?Math.round(score/max*100):0}%`} disabled/></label><label className="full"><span>Комментарий</span><textarea placeholder="Комментарий для родителя"/></label></div><div className="category-picker"><b>Категории теста</b><div>{skillNames.slice(0,6).map((skill)=><button type="button" className={categories.includes(skill)?"active":""} onClick={()=>setCategories((prev)=>prev.includes(skill)?prev.filter(x=>x!==skill):[...prev,skill])} key={skill}>{skill}</button>)}</div></div><div className="form-actions"><Button disabled={invalid||!max} type="submit">Сохранить результат</Button></div></form></SectionCard>;
}

function BulkTestResultsForm({ ui, notify, groupId = "kids-starter" }: { ui: TeacherUI; notify: Notify; groupId?: string }) {
  const { SectionCard, Button }=ui; const students=teacherStudents.filter((s)=>s.groupId===groupId); const max=50; const [scores,setScores]=useState<Record<string,string>>({});
  return <SectionCard title="Массовое заполнение" action={<span className="badge orange">Черновик</span>}><div className="bulk-results"><div className="bulk-head"><span>Ученик</span><span>Балл из {max}</span><span>Процент</span><span>Комментарий</span></div>{students.map((student)=><div key={student.id}><div><span className="avatar">{student.initials}</span><b>{student.name}</b></div><input type="number" min="0" max={max} value={scores[student.id]??""} onChange={(e)=>setScores((prev)=>({...prev,[student.id]:e.target.value}))}/><strong>{scores[student.id]?`${Math.round(Number(scores[student.id])/max*100)}%`:"—"}</strong><input placeholder="Комментарий"/></div>)}</div><CompletionProgress current={Object.values(scores).filter(Boolean).length} total={students.length}/><div className="form-actions"><Button onClick={()=>notify("Результаты группы сохранены")}>Сохранить все результаты</Button></div></SectionCard>;
}

function TestsPage({ ui, groupId, notify = ()=>{}, initialCreate = false }: { ui: TeacherUI; groupId?: string; notify?: Notify; initialCreate?: boolean }) {
  const { SectionCard, Button }=ui; const [mode,setMode]=useState(initialCreate?"single":"list"); const items=teacherTests.filter((test)=>!groupId||test.groupId===groupId);
  if(mode==="single")return <><button className="back-link" onClick={()=>setMode("list")}><ChevronLeft size={16}/>К списку тестов</button><TestResultForm ui={ui} notify={notify}/></>;
  if(mode==="bulk")return <><button className="back-link" onClick={()=>setMode("list")}><ChevronLeft size={16}/>К списку тестов</button><BulkTestResultsForm ui={ui} notify={notify} groupId={groupId}/></>;
  return <><div className="page-toolbar"><TeacherFilters fields={[groupId?groupName(groupId):"Все группы","Все разделы","Май 2025","Все статусы"]}/><div className="toolbar-actions"><Button secondary onClick={()=>setMode("bulk")}>Массовое заполнение</Button><Button onClick={()=>setMode("single")}><Plus size={17}/>Добавить результат</Button></div></div><SectionCard><div className="test-list">{items.map((test)=><article key={test.id}><div><span className="badge green">{test.unit}</span><h3>{test.name}</h3><p>{groupName(test.groupId)} · {test.date}</p></div><div><small>Максимальный балл</small><b>{test.max}</b></div><div><small>Результаты</small><b>{test.completed} / {teacherStudents.filter((s)=>s.groupId===test.groupId).length}</b></div><div><small>Средний результат</small><b>{test.average?`${test.average}%`:"—"}</b></div><span className={`badge ${test.status==="Заполнен"?"green":"orange"}`}>{test.status}</span><button><MoreHorizontal/></button></article>)}</div></SectionCard></>;
}

function SkillScoreInput({ value, onChange }: { value: number | null; onChange: (value:number)=>void }) {
  return <div className={`skill-stepper ${value===null?"empty":""}`}><button type="button" disabled={(value??1)<=1} onClick={()=>onChange(Math.max(1,(value??1)-1))}>−</button><span>{value??"—"}</span><button type="button" disabled={(value??0)>=10} onClick={()=>onChange(Math.min(10,(value??0)+1))}>+</button></div>;
}

function MonthlyAssessmentForm({ ui, notify }: { ui: TeacherUI; notify: Notify }) {
  const { SectionCard, Button }=ui; const students=teacherStudents.slice(0,8); const [current,setCurrent]=useState(0); const [scores,setScores]=useState<Record<string,Record<string,number|null>>>(()=>Object.fromEntries(students.map((s)=>[s.id,Object.fromEntries(skillNames.map((skill)=>[skill,null]))]))); const [status,setStatus]=useState("Черновик"); const filled=students.filter((student)=>skillNames.every((skill)=>scores[student.id][skill]!==null)).length; const selected=students[current];
  const update=(studentId:string,skill:string,value:number)=>setScores((prev)=>({...prev,[studentId]:{...prev[studentId],[skill]:value}}));
  return <><div className="assessment-head"><TeacherFilters fields={["Kids Starter","Май 2025","2025–2026"]}/><span className={`badge ${status==="Черновик"?"orange":"green"}`}>{status}</span></div><CompletionProgress current={filled} total={students.length} label="Оценено учеников"/><SectionCard className="assessment-desktop"><div className="assessment-scroll"><table><thead><tr><th>Ученик</th>{skillNames.map((skill)=><th key={skill}>{skill}</th>)}</tr></thead><tbody>{students.map((student)=><tr key={student.id}><td><b>{student.name}</b></td>{skillNames.map((skill)=><td className={scores[student.id][skill]===null?"empty-score":""} key={skill}><select value={scores[student.id][skill]??""} onChange={(e)=>update(student.id,skill,Number(e.target.value))}><option value="">—</option>{Array.from({length:10},(_,i)=><option key={i+1}>{i+1}</option>)}</select></td>)}</tr>)}</tbody></table></div></SectionCard><SectionCard className="assessment-mobile" title={selected.name} action={<span>{current+1} / {students.length}</span>}><div className="mobile-skills">{skillNames.map((skill)=><div key={skill}><span>{skill}</span><SkillScoreInput value={scores[selected.id][skill]} onChange={(value)=>update(selected.id,skill,value)}/></div>)}</div><div className="student-pager"><Button secondary disabled={current===0} onClick={()=>setCurrent((i)=>i-1)}><ChevronLeft/>Назад</Button><Button secondary disabled={current===students.length-1} onClick={()=>setCurrent((i)=>i+1)}>Следующий<ChevronRight/></Button></div></SectionCard><div className="sticky-save"><span>Заполнено: {filled} из {students.length}</span><Button secondary onClick={()=>{setStatus("Черновик");notify("Черновик оценок сохранён")}}>Сохранить черновик</Button><Button disabled={filled!==students.length} onClick={()=>{setStatus("Опубликовано для родителей");notify("Оценки опубликованы для родителей")}}>Опубликовать</Button></div></>;
}

function ReviewTemplatePicker({ onPick }: { onPick: (text:string)=>void }) { return <aside className="template-picker"><h3>Готовые фразы</h3><p>Нажмите, чтобы добавить в выбранное поле.</p>{reviewTemplates.map((template)=><button type="button" onClick={()=>onPick(template)} key={template}><Plus size={14}/>{template}</button>)}</aside> }

function TeacherReviewForm({ ui, notify }: { ui: TeacherUI; notify: Notify }) {
  const { SectionCard, Button }=ui; const [fields,setFields]=useState({achievements:"",improve:"",recommendations:"",comment:""}); const [active,setActive]=useState<keyof typeof fields>("achievements"); const [status,setStatus]=useState("Черновик"); const [preview,setPreview]=useState(false); const filled=Object.values(fields).filter((v)=>v.trim()).length;
  const set=(key:keyof typeof fields,value:string)=>setFields((prev)=>({...prev,[key]:value}));
  const addTemplate=(text:string)=>set(active,`${fields[active]}${fields[active]?" ":""}${text}`);
  const publish=()=>{if(!filled){notify("Нельзя опубликовать пустой отзыв","error");return}setStatus("Опубликован");notify("Отзыв опубликован для родителей")};
  return <><div className="review-head"><TeacherFilters fields={["Kids Starter","Май 2025","Амина Серикова"]}/><CompletionProgress current={4} total={8} label="Отзывы группы"/></div><div className="review-layout"><SectionCard title="Ежемесячный отзыв" action={<span className={`badge ${status==="Черновик"?"orange":"green"}`}>{status}</span>}><div className="review-form">{[["achievements","Достижения"],["improve","Что необходимо улучшить"],["recommendations","Рекомендации родителям"],["comment","Общий комментарий"]].map(([key,label])=><label className={active===key?"active":""} key={key}><span>{label}</span><textarea value={fields[key as keyof typeof fields]} onFocus={()=>setActive(key as keyof typeof fields)} onChange={(e)=>set(key as keyof typeof fields,e.target.value)} placeholder={`Введите: ${label.toLowerCase()}`}/></label>)}<label><span>Общий уровень прогресса *</span><select><option>Стабильный прогресс</option><option>Значительный прогресс</option><option>Небольшой прогресс</option><option>Без заметных изменений</option><option>Требуется дополнительное внимание</option></select></label></div><div className="form-actions"><Button secondary onClick={()=>setPreview(true)}><Eye size={17}/>Предпросмотр</Button><Button secondary onClick={()=>{setStatus("Черновик");notify("Черновик отзыва сохранён")}}>Сохранить черновик</Button><Button onClick={publish}>{status==="Опубликован"?"Обновить отзыв":"Опубликовать"}</Button></div></SectionCard><ReviewTemplatePicker onPick={addTemplate}/></div>{preview&&<div className="dialog-layer"><div className="review-preview"><button className="sheet-close" onClick={()=>setPreview(false)}><X/></button><span className="badge green">Предпросмотр для родителя</span><h2>Май 2025 · Амина Серикова</h2><p className="label">Достижения</p><p>{fields.achievements||"Не заполнено"}</p><p className="label">Что улучшить</p><p>{fields.improve||"Не заполнено"}</p><p className="label">Рекомендации</p><p>{fields.recommendations||"Не заполнено"}</p><p className="label">Общий комментарий</p><p>{fields.comment||"Не заполнено"}</p><div className="teacher-sign"><span className="avatar">АС</span><div><b>{teacherProfile.name}</b><small>Учитель английского языка</small></div></div></div></div>}</>;
}

function StudentProgress({ title = "Динамика навыков" }: { title?: string }) { return <section className="section-card"><div className="section-head"><h2>{title}</h2><span className="badge green">6 месяцев</span></div><div className="chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={progressData}><CartesianGrid stroke="#eef0f3" vertical={false}/><XAxis dataKey="month" tickLine={false}/><YAxis domain={[0,10]} tickLine={false}/><Tooltip/><Line dataKey="Speaking" stroke="#ff1028" strokeWidth={3}/><Line dataKey="Listening" stroke="#ff8a00" strokeWidth={2}/><Line dataKey="Reading" stroke="#2878ee" strokeWidth={2}/></LineChart></ResponsiveContainer></div></section> }

function StudentProfile({ ui, studentId }: { ui: TeacherUI; studentId: string }) {
  const { SectionCard }=ui; const student=teacherStudents.find((item)=>item.id===studentId)??teacherStudents[0]; const group=teacherGroups.find((item)=>item.id===student.groupId)!; const [tab,setTab]=useState("Обзор");
  return <><Link className="back-link" href="/teacher/students"><ChevronLeft size={16}/>Все ученики</Link><section className="student-profile-header"><span className="student-avatar small">{student.initials}</span><div><span className="badge green">Активен</span><h2>{student.name}</h2><p>{student.age} лет · {group.name} · {student.level} · {group.book}</p></div><div className="profile-contact"><small>Родитель</small><b>{student.parent}</b><span>{student.phone}</span></div></section><div className="teacher-quick-grid profile-actions"><Link href="/teacher/tests?create=1"><Star/>Добавить результат<ChevronRight/></Link><Link href="/teacher/homework"><ClipboardCheck/>Статус ДЗ<ChevronRight/></Link><Link href="/teacher/grades"><ListChecks/>Выставить оценки<ChevronRight/></Link><Link href="/teacher/feedback"><MessageSquareText/>Написать отзыв<ChevronRight/></Link></div><div className="tabs group-tabs">{["Обзор","Посещаемость","Темы","Слова","Домашние задания","Тесты","Навыки","Отзывы","История"].map((item)=><button className={tab===item?"active":""} onClick={()=>setTab(item)} key={item}>{item}</button>)}</div>{tab==="Навыки"?<StudentProgress/>:tab==="История"?<SectionCard><div className="timeline">{[["30 мая 2025","Пройден урок My Family","Добавлено 8 новых слов"],["26 мая 2025","Unit 2 Test — 82%","Сильный результат по Vocabulary"],["10 мая 2025","Опубликован ежемесячный отзыв","Стабильный прогресс"],[student.startedAt,"Начало обучения",`${group.name} · ${student.level}`]].map(([date,title,text])=><div key={date}><i><Check size={15}/></i><time>{date}</time><h3>{title}</h3><p>{text}</p></div>)}</div></SectionCard>:<><div className="student-metrics"><article><span>Посещаемость</span><b>{student.attendance}%</b><small>за май</small></article><article><span>Последний тест</span><b>{student.lastTest}%</b><small>Unit 2 Test</small></article><article><span>Освоено слов</span><b>34</b><small>за период</small></article><article><span>Домашние задания</span><b>6 / 7</b><small>выполнено</small></article></div><StudentProgress/><div className="dashboard-columns"><SectionCard title="Обучение"><dl className="overview-dl"><div><dt>Дата начала</dt><dd>{student.startedAt}</dd></div><div><dt>Группа</dt><dd>{group.name}</dd></div><div><dt>Учебник</dt><dd>{group.book}</dd></div><div><dt>Текущая тема</dt><dd>{group.topic}</dd></div></dl></SectionCard><SectionCard title="Последний отзыв"><p>Уверенно использует новые слова и активно участвует в работе на уроке.</p><p className="muted">Рекомендуется больше практиковать письменную речь.</p></SectionCard></div></>}</>;
}

function TeacherProfile({ ui }: { ui: TeacherUI }) { const { SectionCard, Button }=ui; return <div className="dashboard-columns"><SectionCard title="Профиль учителя"><div className="profile-hero"><span className="avatar big">АС</span><div><h3>{teacherProfile.name}</h3><p>Учитель английского языка</p></div></div><dl className="profile-dl"><div><dt>Email</dt><dd>{teacherProfile.email}</dd></div><div><dt>Телефон</dt><dd>{teacherProfile.phone}</dd></div><div><dt>Учебный период</dt><dd>{teacherProfile.period}</dd></div></dl><Button secondary>Редактировать профиль</Button></SectionCard><SectionCard title="Моя нагрузка"><div className="student-metrics profile-metrics"><article><span>Группы</span><b>3</b></article><article><span>Ученики</span><b>24</b></article><article><span>Уроки в неделю</span><b>9</b></article><article><span>Текущий период</span><b>2025–26</b></article></div></SectionCard></div> }

export function TeacherPortal({ page, ui }: { page: string; ui: TeacherUI }) {
  const pathname=usePathname(); const searchParams=useSearchParams(); const parts=pathname.split("/").filter(Boolean); const entityId=parts[2]; const queryGroup=searchParams.get("group")??undefined; const initialCreate=searchParams.get("create")==="1"; const [toast,setToast]=useState<{message:string;tone:string}|null>(null); const notify:Notify=(message,tone="success")=>setToast({message,tone});
  let content:React.ReactNode;
  if(page==="home")content=<TeacherDashboard ui={ui}/>;
  else if(page==="groups")content=entityId?<GroupPage ui={ui} groupId={entityId}/>:<GroupsList/>;
  else if(page==="attendance")content=<AttendanceRegister ui={ui} groupId={queryGroup??"kids-starter"}/>;
  else if(page==="lessons"||page==="lesson")content=<LessonsJournal ui={ui} groupId={queryGroup} notify={notify} initialCreate={initialCreate}/>;
  else if(page==="homework")content=<HomeworkPage ui={ui} groupId={queryGroup} notify={notify} initialCreate={initialCreate}/>;
  else if(page==="words")content=<WordsPage ui={ui} notify={notify}/>;
  else if(page==="tests")content=<TestsPage ui={ui} groupId={queryGroup} notify={notify} initialCreate={initialCreate}/>;
  else if(page==="grades")content=<MonthlyAssessmentForm ui={ui} notify={notify}/>;
  else if(page==="feedback")content=<TeacherReviewForm ui={ui} notify={notify}/>;
  else if(page==="students")content=entityId?<StudentProfile ui={ui} studentId={entityId}/>:<ui.SectionCard title="Мои ученики"><StudentList/></ui.SectionCard>;
  else if(page==="profile")content=<TeacherProfile ui={ui}/>;
  else content=<TeacherDashboard ui={ui}/>;
  return <>{content}{toast&&<Toast message={toast.message} tone={toast.tone} onClose={()=>setToast(null)}/>}</>;
}
